namespace Gordic.Pok.WebClient {


  

    @Decorators.gcontent
    export class GPokVycetkaTab extends GContentBase {

        private grid: JQuery<HTMLElement>;
        menaZkr: string;
        mena: number;
        ixpDen: string;    
        castka: Decimal;     

        onContentReady() {

            this.title = "Výčetka";

            var that = this;

            this.setBreadcrumbs([{ caption: this.title, defaultAction : true }]);



            Gordic.Isl.PokKniha.platidlaKnihy(rq => {
                return {
                    filters: {
                        ixp_den: that.ixpDen,
                        aktivita: 100
                    }
                }               
            })
                .getData().done(function (data) {  


                    let vyslednaData: Gordic.Hpl.Interface.GPokEkodmenDto[];
                    vyslednaData = [];                   

                    that.vyplnVycetku(parseDecimal(that.castka),data)
                        .done(function (dataPocet) {

                          

                            let bankovky = dataPocet.filter(x => x.typ_platidla == 20 || x.typ_platidla == 30).map(x => $.extend(true, {}, x));;//Bankovyk a Bankovky a Mince
                            let bankovkyMince = dataPocet.filter(x => x.typ_platidla == 30).map(x => $.extend(false, {}, x)); // Typ platidla Bankovky a Mince
                            let bankovkyMinceHodnota = bankovkyMince.map(x => x.c!);
                            let mince = dataPocet.filter(x => x.typ_platidla == 10 || x.typ_platidla == 30 || x.typ_platidla == 0).map(x => $.extend(true, {}, x));; //Mince s Bankovky a mince a Neurčeno


                            bankovky.forEach(function (x) {

                                x.celkem = parseDecimal(x.c!).mul(x.pocet!);
                                x.typ_platidla = 20; // bankovka
                                vyslednaData.push(x);
                            })

                            mince.forEach(function (y) {

                                if (bankovkyMinceHodnota.indexOf(y.c!) > -1) {
                                    //pokud už je v bankovkách
                                    //ještě by šlo otestovat, že je typ_platidla 30 (mince a bankovky)
                                    y.pocet = 0;
                                }
                                y.celkem = parseDecimal(y.c!).mul(y.pocet!);
                                y.typ_platidla = 10;
                                vyslednaData.push(y);
                            })

                          
                            //let y = bankovky.length;
                            //if (mince.length > y)
                            //    y = mince.length;  

                            //for (let i = 0; i < y; i++) {

                            //    if (bankovkyMinceHodnota.indexOf(mince[i].c!) > -1) {
                            //        mince[i].pocet = 0;
                            //    }
                             
                            //    vyslednaData.push({
                            //        platidlo_bankovka: (bankovky[i] ? bankovky[i].c : ""),
                            //        pocet_bankovka: (bankovky[i] ? bankovky[i].pocet : ""),
                            //        celkem_bankovka: (bankovky[i] ? parseDecimal(bankovky[i].c!).mul(bankovky[i].pocet!) : ""),
                            //        oddelovac: "X",
                            //        platidlo_mince: (mince[i] ? mince[i].c : ""),
                            //        pocet_mince: (mince[i] ? mince[i].pocet : ""),
                            //        celkem_mince: (mince[i] ? parseDecimal(mince[i].c!).mul(mince[i].pocet!) : ""),
                            //    })                                
                            //}  
                        })

    
                    
                   

            var headerForm = new Gordic.Forms.Form({ name: "pokVycetkaForm", layoutDescriptor: "L3M3S3" })
                .addSection()
                .addRow("Celkem " + that.menaZkr) //RC 31302291 : Hodnota
                .addField("gnumberbox", Gordic.Prefabs.Number.currency(), {
                    name: "celkem", disabled: true
                })
                .addSection()
                .addRow("Bankovky " + that.menaZkr) 
                .addField("gnumberbox", Gordic.Prefabs.Number.currency(),{
                    name: "celkem_bankovky", disabled: true            
                })               
                .addSection()
                .addRow("Mince " + that.menaZkr) //RC 31302292 : Celková hodnota
                .addField("gnumberbox", Gordic.Prefabs.Number.currency(),
                    { name: "celkem_mince", disabled: true });

            var tab = $("<div>").appendTo(that.element).gform("createFrom", headerForm);

                    that.grid =
                        $("<div>").appendTo(that.element)
                        .ggrid({
                            data: new Gordic.Data.View(vyslednaData, {
                                key: "c,typ_platidla" }),                         
                                renderMode: "auto",     // auto, all-at-once, paged-sync, paged-async
                                columnMode: "fit",      // fit, full
                                navigationMode: "row", // row, cell
                                rowNumbers: false,
                                filtering: false,
                            profileVisible: false,                                
                                showTopPanel: false,
                                columns: new Gordic.Data.GridFormat()
                                    .addNumberColumn(
                                        {
                                            name: "c",
                                            caption: "Platidlo",
                                            sortable: false,

                                        })
                                    .addNumberColumn(
                                        {
                                            name: "pocet",
                                            caption: "Počet",
                                            sortable: false,
                                            editor: {
                                                widget: "gnumberbox",
                                                options: [{
                                                    name: "pocet",
                                                    change: function () {                                                     
                                                        var radek = that.grid.ggrid("getSelection")[0];
                                                        radek.celkem = Decimal.mul(radek.pocet, radek.c);

                                                        let view = that.grid.ggrid("getView");
                                                        view.updateData(radek, "update");

                                                        that.vypocetCelkem();

                                                      
                                                    }
                                                    }]
                                            
                                            }

                                        })
                                    .addNumberColumn(
                                        {
                                            name: "celkem",
                                            caption: "Celkem",
                                            sortable: false,

                                        })
                                    .addTextColumn(
                                        {
                                            name: "typ_platidla_txt",
                                            caption: "Typ platidla",
                                            sortable: false,

                                        })                                   

                        }).ggridcelleditor();


                    that.vypocetCelkem();
                })

            that.actions.addRange({
                actMincovka: {
                    caption: "Mincovka",
                    icon: "",
                    run: function (ev, ctx) {     
                      
                        var ParamsJSON = { };
                        var selectWindow = that.navigate("Gordic.Pok.WebClient.GPokMincovkaTab", ParamsJSON);
                        var windowContent = $.content(selectWindow);
                        windowContent.close(function (vystup: any) {



                            let view = that.grid.ggrid<Gordic.Hpl.Interface.GPokEkodmenDto>("getView");
                            let data = view.getDataRows();

                            data.forEach(function (row) {

                                row.pocet = 0;
                                row.celkem = parseDecimal(0);
                            });


                            let mince = view.getDataRows().filter(x => x.aktivita == 100).map(x => $.extend(true, {}, x));;  

                          

                            if (mince.findIndex(x => parseDecimal(x.c!).equals(vystup.castka)) > -1) {
                                //existuje platidlo s takovou hodnotou
                                let index = data.findIndex(x => parseDecimal(x.c!).equals(vystup.castka))
                                data[index].pocet = data[index].pocet! + Number(vystup.kolikrat);
                                data[index].celkem = parseDecimal(data[index].c!).mul(data[index].pocet!); 

                            }
                            else {
                                //pokud neexistuje, tak celkovou částku rozpočítám do mincí

                                //let celkovaCastka = parseDecimal(vystup.kolikrat).mul(vystup.castka);
                                let celkovaCastka = vystup.castka;
                                mince.forEach(function (hodnota) {
                                   
                                    while (Decimal.max(celkovaCastka, celkovaCastka.mul(-1)).greaterThanOrEqualTo(hodnota.c!)) {


                                        if (celkovaCastka.isNegative()) {

                                            celkovaCastka = celkovaCastka.plus(hodnota.c!);
                                            let index = data.findIndex(x => parseDecimal(x.c!).equals(hodnota.c!))
                                            data[index].pocet! += parseDecimal(1).mul(vystup.kolikrat).toNumber();
                                            data[index].celkem = parseDecimal(data[index].c!).mul(data[index].pocet!); 
                                        }
                                        else {
                                            celkovaCastka = celkovaCastka.minus(hodnota.c!);
                                            let index = data.findIndex(x => parseDecimal(x.c!).equals(hodnota.c!))
                                            data[index].pocet! += parseDecimal(1).mul(vystup.kolikrat).toNumber();
                                            data[index].celkem = parseDecimal(data[index].c!).mul(data[index].pocet!); 
                                        }
                                    } //end while


                                    if (parseDecimal(celkovaCastka).isZero()) {
                                        view.updateData(data, "update");
                                        that.vypocetCelkem();
                                    }

                                })         

                            }  

                        });

                        
                    }
                },
                actVycistit: {
                    caption: "Vyčistit",
                    icon: "",
                    run: function (ev, ctx) {
                        that.vycistit();
                       
                    }
                },
                actTisk: {
                    caption: "Tisk",
                    icon: "",
                    run: function (ev, ctx) {
                        that.tisk();
                    }
                }               
            })
            this.menuBar([
                { action: this.actions.actMincovka, favorite: true },
                { action: this.actions.actVycistit, favorite: true },
                { action: this.actions.actTisk, favorite: true }               
            ]);
        }

        private tisk(): void {

            var that = this;

            var actTiskVycetka = GAction.createPrintAction({
                name: "actTiskVycetka",
                caption: "Tisk",
                tema: "pok_ptm_vycetka",  
                serverParameterMethod: "Gordic.Pok.WebClient.GPokWebTisk:Vycetka",
                reportStarting: function (rep) {
                    rep.customDto = { vycetkaMena: that.mena, vycetkaMenaZkr: that.menaZkr, vycetkaCelkem: that.element.findFields("celkem").gfield("getValue"), ixp_den: that.ixpDen, vycetkaVycet: that.grid.ggrid("getView").getDataRows() }
                },
                reportFinished: function (event, retVal) {

                }
            });
            actTiskVycetka.run();
           

        }

        private vycistit(): void {

            var that = this;

            let view = that.grid.ggrid("getView");
            let data = view.getDataRows();

            data.forEach(function (row) {              
                row.pocet = 0;
                    row.celkem = 0;               
            })


            view.updateData(data, "update");

            that.element.findFields("celkem_bankovky").gfield("setValue", 0);
            that.element.findFields("celkem").gfield("setValue", 0);
            that.element.findFields("celkem_mince").gfield("setValue", 0);

        }



        private vyplnVycetku(celkovaCastka: Decimal, hodnoty: Gordic.Hpl.Interface.GPokEkodmenDto[]): JQueryPromise<Gordic.Hpl.Interface.GPokEkodmenDto[]>
        {
            var that = this;

            var def = $.Deferred();


            hodnoty.forEach(function (hodnota) {

                hodnota.pocet = 0;
                while (Decimal.max(celkovaCastka, celkovaCastka.mul(-1)).greaterThanOrEqualTo(hodnota.c!)) {

                   
                    if (celkovaCastka.isNegative() ){

                        celkovaCastka = celkovaCastka.plus(hodnota.c!);
                        hodnota.pocet = hodnota.pocet - 1;
                    }
                    else {
                        celkovaCastka = celkovaCastka.minus(hodnota.c!);
                        hodnota.pocet = hodnota.pocet + 1;
                    }
                }
            })         

            return def.resolve(hodnoty);

        }

        private vypocetCelkem(): void {

            var that = this;

            let view = that.grid.ggrid("getView");
          
            let bankovykHodnotaArr = view.getDataRows().filter(x => x.typ_platidla == 20).map(x => $.extend(true, {}, x));;
            let minceHodnotaArr = view.getDataRows().filter(x => x.typ_platidla == 10).map(x => $.extend(true, {}, x));;

            let bankovkyCelkem = new Decimal(0);
            let minceCelkem = new Decimal(0);
            let celkem = new Decimal(0);

            for (var i = 0; i < bankovykHodnotaArr.length; i++) {
                if (bankovykHodnotaArr[i])
                    bankovkyCelkem = Decimal.add(bankovkyCelkem, bankovykHodnotaArr[i].celkem);

            }

            for (var i = 0; i < minceHodnotaArr.length; i++) {
                if (minceHodnotaArr[i])
                    minceCelkem = Decimal.add(minceCelkem, minceHodnotaArr[i].celkem);

            }

            celkem = Decimal.add(bankovkyCelkem, minceCelkem);

            that.element.findFields("celkem_bankovky").gfield("setValue", bankovkyCelkem);
            that.element.findFields("celkem").gfield("setValue", celkem);
            that.element.findFields("celkem_mince").gfield("setValue", minceCelkem);

        }

        
    }
}